declare v_expected jsonb := $schema_baseline${"at":"2026-11-13T04:53:28.849667+00:00","tables":[{"acl":["postgres=arwdDxtm/postgres","anon=arwdDxtm/postgres","authenticated=arwdDxtm/postgres","service_role=arwdDxtm/postgres"],"rls":true,"name":"clients","owner":"postgres","columns":[{"name":"id","type":"uuid","default":"gen_random_uuid()","nullable":false},{"name":"zone_id","type":"uuid","default":null,"nullable":true},{"name":"document_type","type":"document_type","default":"'cedula'::document_type","nullable":false},{"name":"document_number","type":"text","default":null,"nullable":false},{"name":"first_name","type":"text","default":null,"nullable":false},{"name":"last_name","type":"text","default":null,"nullable":false},{"name":"phone","type":"text","default":null,"nullable":true},{"name":"email","type":"text","default":null,"nullable":true},{"name":"birthdate","type":"date","default":null,"nullable":true},{"name":"status","type":"client_status","default":"'prospect'::client_status","nullable":false},{"name":"created_at","type":"timestamp with time zone","default":"now()","nullable":false},{"name":"updated_at","type":"timestamp with time zone","default":"now()","nullable":false},{"name":"address","type":"text","default":null,"nullable":true},{"name":"latitude","type":"double precision","default":null,"nullable":true},{"name":"longitude","type":"double precision","default":null,"nullable":true},{"name":"client_code","type":"text","default":null,"nullable":true},{"name":"phone_2","type":"text","default":null,"nullable":true},{"name":"saldo_a_favor","type":"numeric(10,2)","default":"0","nullable":false}],"indexes":[{"name":"clients_document_number_key","definition":"CREATE UNIQUE INDEX clients_document_number_key ON public.clients USING btree (document_number)"},{"name":"clients_pkey","definition":"CREATE UNIQUE INDEX clients_pkey ON public.clients USING btree (id)"},{"name":"idx_clients_client_code_unique","definition":"CREATE UNIQUE INDEX idx_clients_client_code_un