ated_at = now();\r\n  return new;\r\nend;\r\n$function$\n"}],"force_rls":false,"constraints":[{"name":"clients_document_number_key","definition":"UNIQUE (document_number)"},{"name":"clients_pkey","definition":"PRIMARY KEY (id)"},{"name":"clients_zone_id_fkey","definition":"FOREIGN KEY (zone_id) REFERENCES zones(id)"}]},{"acl":["postgres=arwdDxtm/postgres","anon=arwdDxtm/postgres","authenticated=arwdDxtm/postgres","service_role=arwdDxtm/postgres"],"rls":true,"name":"installations","owner":"postgres","columns":[{"name":"id","type":"uuid","default":"gen_random_uuid()","nullable":false},{"name":"client_id","type":"uuid","default":null,"nullable":false},{"name":"contract_id","type":"uuid","default":null,"nullable":true},{"name":"status","type":"installation_status","default":"'pending'::installation_status","nullable":false},{"name":"scheduled_date","type":"date","default":null,"nullable":true},{"name":"scheduled_time","type":"time without time zone","default":null,"nullable":true},{"name":"assigned_to","type":"uuid","default":null,"nullable":true},{"name":"notes","type":"text","default":null,"nullable":true},{"name":"completed_at","type":"timestamp with time zone","default":null,"nullable":true},{"name":"created_by","type":"uuid","default":"auth.uid()","nullable":true},{"name":"created_at","type":"timestamp with time zone","default":"now()","nullable":false},{"name":"updated_at","type":"timestamp with time zone","default":"now()","nullable":false},{"name":"iptv_account_note","type":"text","default":null,"nullable":true},{"name":"scheduled_start_at","type":"timestamp with time zone","default":null,"nullable":true},{"name":"scheduled_end_at","type":"timestamp with time zone","default":null,"nullable":true},{"name":"priority","type":"ticket_priority","default":"'medium'::ticket_priority","nullable":false},{"name":"alerta_enviada","type":"boolean","default":"false","nullable":false},{"name":"points","type":"numeric","default":null,"nullable":true},{"name":"iptv_policy_version","type":"smallint","default":"1","nullable":true},{"name":"iptv_installation_mode","type":"text","default":null,"nullable":true},{"name":"closure_operation_id","type":"uuid","default":null,"nullable":true},{"name":"closure_payload_hash","type":"text","default":null,"nullable":true}],"indexes":[{"name":"idx_installations_client_id","definition":"CREATE INDEX idx_installations_client_id ON public.installations USING btree (client_id)"},{"name":"idx_installations_contract_id","definition":"CREATE INDEX idx_installations_contract_id ON public.installations USING btree (contract_id)"},{"name":"idx_installations_status","definition":"CREATE INDEX idx_installations_status ON public.installations USING btree (status)"},{"name":"installations_pkey","definition":"CREATE UNIQUE INDEX installations_pkey ON public.installations USING btree (id)"}],"policies":[{"cmd":"DELETE","name":"installations_delete_staff","check":null,"roles":["authenticated"],"using":"((status = 'cancelled'::installation_status) AND (current_user_role() = ANY (ARRAY['SUPERADMIN'::user_role, 'ADMIN'::user_role, 'SOPORTE'::user_role, 'FACTURACION'::user_role])))","permissive":"PERMISSIVE"},{"cmd":"INSERT","name":"installations_insert_staff","check":"(current_user_role() = ANY (ARRAY['SUPERADMIN'::user_role, 'ADMIN'::user_role, 'SOPORTE'::user_role, 'FACTURACION'::user_role]))","roles":["authenticated"],"using":null,"permissive":"PERMISSIVE"},{"cmd":"SELECT","name":"installations_select_staff","check":null,"roles":["authenticated"],"using":"(current_user_role() = ANY (ARRAY['SUPERADMIN'::user_role, 'ADMIN'::user_role, 'TECNICO_RED'::user_role, 'SOPORTE'::user_role, 'FACTURACION'::user_role]))","permissive":"PERMISSIVE"},{"cmd":"UPDATE","name":"installations_update_staff","check":"((current_user_role() = ANY (ARRAY['SUPERADMIN'::user_role, 'ADMIN'::user_role])) OR ((current_user_role() = 'TECNICO_RED'::user_role) AND (EXISTS ( SELECT 1\n   FROM job_assignees ja\n  WHERE ((ja.job_type = 'installation'::text) AND (ja.job_id = installations.id) AND (ja.technician_id = auth.uid()))))))","roles":["authenticated"],"using":"((current_user_role() = 'SUPERADMIN'::user_role) OR ((current_user_role() = 'ADMIN'::user_role) AND (status <> ALL (ARRAY['completed'::installation_status, 'cancelled'::installation_status]))) OR ((current_user_role() = 'TECNICO_RED'::user_role) AND (status <> ALL (ARRAY['completed'::installation_status, 'cancelled'::installation_status])) AND (EXISTS ( SELECT 1\n   FROM job_assignees ja\n  WHERE ((ja.job_type = 'installation'::text) AND (ja.job_id = installations.id) AND (ja.technician_id = auth.uid()))))))","permissive":"PERMISSIVE"}],"triggers":[{"name":"a_guard_final_work_order","enabled":"O","function":"guard_final_work_order()","definition":"CREATE TRIGGER a_guard_final_work_order BEFORE DELETE OR UPDATE ON public.installations FOR EACH ROW EXECUTE FUNCTION guard_final_work_order()","function_definition":"CREATE OR REPLACE FUNCTION public.guard_final_work_order()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare contexts jsonb:='[]'; target record; tbl text;\nbegin\n  if tg_table_name='job_assignees' then\n    if tg_op<>'INSERT' then contexts:=contexts||jsonb_build_array(jsonb_build_object('kind',old.job_type,'id',old.job_id)); end if;\n    if tg_op<>'DELETE' then contexts:=contexts||jsonb_build_array(jsonb_build_object('kind',new.job_type,'id',new.job_id)); end if;\n  else\n    contexts:=jsonb_build_array(jsonb_build_object('kind',case tg_table_name when 'tickets' then 'ticket' when 'installations' then 'installation' else 'routine' end,'id',old.id));\n  end if;\n  for target in select distinct c->>'kind' as kind,(c->>'id')::uuid as id from jsonb_array_elements(contexts)c order by 1,2 loop\n    if tg_table_name='job_assignees' then\n      tbl:=case target.kind when 'ticket' then 'tickets' when 'installation' then 'installations' else 'routines' end;\n      -- Serializar cambios de cuadrilla con la misma fila que confirma la RPC.\n      execute format('select 1 from public.%I where id=$1 for update',tbl) using target.id;\n    end if;\n    if exists(select 1 from public.work_order_point_confirmations where job_type=target.kind and job_id=target.id) then\n      raise exception 'Cierre administrativo definitivo: la orden y su cuadrilla no se pueden modificar ni reabrir. Crea una nueva orden.' using errcode='P0001';\n    end if;\n  end loop;\n  if tg_op='DELETE' then return old; end if;\n  return new;\nend;\n$function$\n"},{"name":"b_installation_iptv_insert","enabled":"O","function":"guard_installation_iptv_policy()","definition":"CREATE TRIGGER b_installation_iptv_insert BEFORE INSERT ON public.installations FOR EACH ROW EXECUTE FUNCTION guard_installation_iptv_policy()","function_definition":"CREATE OR REPLACE FUNCTION public.guard_installation_iptv_policy()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nbegin\n if tg_op='INSERT' then\n  new.iptv_policy_version:=1;\n  if new.status::text in ('completed','cancelled') then\n   raise exception 'Crea la nueva Alta abierta y completa sus validaciones antes de cerrarla' using errcode='PIP00';\n  end if;\n elsif new.iptv_policy_version is distinct from old.iptv_policy_version then\n  raise exception 'La regla IPTV de la orden no se puede cambiar' using errcode='PIP01';\n elsif old.iptv_policy_version is null and (new.iptv_installation_mode,new.closure_operation_id,new.closure_payload_hash) is distinct from (old.iptv_installation_mode,old.closure_operation_id,old.closure_payload_hash) then\n  raise exception 'No se modifica la modalidad IPTV de órdenes anteriores' using errcode='PIP02';\n elsif old.status::text in ('completed','cancelled') and (new.iptv_installation_mode,new.closure_operation_id,new.closure_payload_hash) is distinct from (old.iptv_installation_mode,old.closure_operation_id,old.closure_payload_hash) then\n  raise exception 'La modalidad IPTV de una orden cerrada no se puede cambiar' using errcode='PIP03';\n elsif (new.client_id,new.contract_id) is distinct from (old.client_id,old.contract_id) and new.iptv_installation_mode is not null then\n  raise exception 'El cliente o contrato cambió; revisa la modalidad IPTV antes del cierre' using errcode='PIP04';\n end if;\n return new;\nend $function$\n"},{"name":"b_installation_iptv_update","enabled":"O","function":"guard_installation_iptv_policy()","definition":"CREATE TRIGGER b_installation_iptv_update BEFORE UPDATE ON public.installations FOR EACH ROW EXECUTE FUNCTION guard_installation_iptv_policy()","function_definition":"CREATE OR REPLACE FUNCTION public.guard_installation_iptv_policy()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nbegin\n if tg_op='INSERT' then\n  new.iptv_policy_version:=1;\n  if new.status::text in ('completed','cancelled') then\n   raise exception 'Crea la nueva Alta abierta y completa sus validaciones antes de cerrarla' using errcode='PIP00';\n  end if;\n elsif new.iptv_policy_version is distinct from old.iptv_policy_version then\n  raise exception 'La regla IPTV de la orden no se puede cambiar' using errcode='PIP01';\n elsif old.iptv_policy_version is null and (new.iptv_installation_mode,new.closure_operation_id,new.closure_payload_hash) is distinct from (old.iptv_installation_mode,old.closure_operation_id,old.closure_payload_hash) then\n  raise exception 'No se modifica la modalidad IPTV de órdenes anteriores' using errcode='PIP02';\n elsif old.status::text in ('completed','cancelled') and (new.iptv_installation_mode,new.closure_operation_id,new.closure_payload_hash) is distinct from (old.iptv_installation_mode,old.closure_operation_id,old.closure_payload_hash) then\n  raise exception 'La modalidad IPTV de una orden cerrada no se puede cambiar' using errcode='PIP03';\n elsif (new.client_id,new.contract_id) is distinct from (old.client_id,old.contract_id) and new.iptv_installation_mode is not null then\n  raise exception 'El cliente o contrato cambió; revisa la modalidad IPTV antes del cierre' using errcode='PIP04';\n end if;\n return new;\nend $function$\n"},{"name":"contract_administrative_installation_guard","enabled":"O","function":"contract_administrative_installation_guard()","definition":"CREATE TRIGGER contract_administrative_installation_guard BEFORE INSERT OR UPDATE OF status, client_id, contract_id ON public.installations FOR EACH ROW EXECUTE FUNCTION contract_administrative_installation_guard()","function_definition":"CREATE OR REPLACE FUNCTION public.contract_administrative_installation_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\ndeclare previous_parent uuid; parent_status public.client_status; contract_parent uuid; contract_status public.contract_status;\nbegin\n if tg_op='UPDATE' then previous_parent:=old.client_id; end if;\n perform 1 from public.clients where id in (new.client_id,previous_parent) order by id for update;\n select status into parent_status from public.clients where id=new.client_id;\n if parent_status is null then raise exception 'No se puede validar la ficha' using errcode='42501'; end if;\n if new.status::text in ('pending','scheduled','in_progress') then\n  if parent_status='retired' then raise exception 'Ficha retirada; Alta inconsistente' using errcode='PBA02'; end if;\n  if new.contract_id is not null then\n   select client_id,status into contract_parent,contract_status from public.service_contracts where id=new.contract_id;\n   if contract_parent is distinct from new.client_id or contract_status='cancelled' then raise exception 'Alta incompatible con el contrato' using errcode='PBA02'; end if;\n  end if;\n end if;\n return new;\nend $function$\n"},{"name":"guard_material_installation","enabled":"O","function":"guard_rejected_material_closure()","definition":"CREATE TRIGGER guard_material_installation BEFORE UPDATE OF status ON public.installations FOR EACH ROW EXECUTE FUNCTION guard_rejected_material_closure()","function_definition":"CREATE OR REPLACE FUNCTION public.guard_rejected_material_closure()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nbegin\n if tg_table_name='work_order_closures' then\n   perform public.lock_material_inventory_job(new.job_type::text,new.job_id);\n   perform public.assert_no_rejected_materials(new.job_type::text,new.job_id);\n elsif tg_table_name='installations' then\n   if new.status::text='completed' and new.status is distinct from old.status then perform public.assert_no_rejected_materials('installation',new.id); end if;\n elsif tg_table_name='tickets' then\n   if new.status::text in ('resolved','closed') and new.status is distinct from old.status then perform public.assert_no_rejected_materials('ticket',new.id); end if;\n elsif tg_table_name='routines' then\n   if new.status::text='completed' and new.status is distinct from old.status then perform public.assert_no_rejected_materials('routine',new.id); end if;\n end if;\n return new;\nend $function$\n"},{"name":"guard_work_order_points","enabled":"O","function":"guard_work_order_points()","definition":"CREATE TRIGGER guard_work_order_points BEFORE INSERT OR UPDATE ON public.installations FOR EACH ROW EXECUTE FUNCTION guard_work_order_points()","function_definition":"CREATE OR REPLACE FUNCTION public.guard_work_order_points()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_reason text; v_role text; kind text; done timestamptz; prospect_zero boolean:=false;\nbegin\n  if tg_table_name='installations' then\n    prospect_zero:=public.is_prospect_conversion_installation(new.id,new.client_id,new.contract_id);\n    if new.points=0 then\n      if not prospect_zero then raise exception 'Cero puntos solo para un Alta creada por conversión atómica de Prospecto'; end if;\n      if tg_op='UPDATE' and old.points is distinct from new.points then\n        raise exception 'Los puntos solo pueden ser cero al crear el Alta de Prospecto';\n      end if;\n      if tg_op='INSERT' then return new; end if;\n    end if;\n  end if;\n  if tg_op='INSERT' then\n    if new.points is null or not(new.points>0 and new.points<'Infinity'::numeric) then raise exception 'La orden requiere puntos mayores a 0'; end if;\n    return new;\n  end if;\n  if new.points is not distinct from old.points then return new; end if;\n  select role::text into v_role from public.profiles where id=auth.uid() and active;\n  if v_role is null or v_role not in ('ADMIN','SUPERADMIN') then raise exception 'Solo ADMIN/SUPERADMIN puede ajustar puntos'; end if;\n  kind:=case tg_table_name when 'tickets' then 'ticket' when 'installations' then 'installation' else 'routine' end;\n  if old.status::text='cancelled' or new.status::text='cancelled' then raise exception 'La orden está cancelada'; end if;\n  if exists(select 1 from public.work_order_point_confirmations c where c.job_type=kind and c.job_id=old.id) then\n    raise exception 'Los puntos ya están confirmados';\n  end if;\n  done:=case when kind='ticket' then coalesce((to_jsonb(old)->>'resolved_at')::timestamptz,(to_jsonb(old)->>'closed_at')::timestamptz)\n    else (to_jsonb(old)->>'completed_at')::timestamptz end;\n  -- Fin de la ventana productiva documentada: antes de ella son terminaciones\n  -- históricas protegidas; después, órdenes pendientes de revisión del piloto.\n  -- El corte de acreditación oficial de noviembre NO se usa como cierre.\n  if ((done is not null and done<timestamptz '2026-10-26 04:22:51+00')\n      or (done is null and old.status::text in ('resolved','closed','completed')))\n     and not(kind='installation' and prospect_zero and old.points=0) then\n    raise exception 'No se modifican puntos históricos anteriores a la activación';\n  end if;\n  if new.points is null or not(new.points>0 and new.points<'Infinity'::numeric) then raise exception 'La orden requiere puntos mayores a 0'; end if;\n  v_reason:=nullif(btrim(current_setting('smartrayco.points_reason',true)),'');\n  if v_reason is null or length(v_reason)>1000 then raise exception 'Utiliza el ajuste administrativo con motivo obligatorio'; end if;\n  insert into public.work_order_point_changes(job_type,job_id,old_points,new_points,changed_by,reason)\n  values(kind,old.id,old.points,new.points,auth.uid(),v_reason);\n  return new;\nend;\n$function$\n"},{"name":"trg_installations_completed_at","enabled":"O","function":"set_installation_completed_at()","definition":"CREATE TRIGGER trg_installations_completed_at BEFORE UPDATE ON public.installations FOR EACH ROW EXECUTE FUNCTION set_installation_completed_at()","function_definition":"CREATE OR REPLACE FUNCTION public.set_installation_completed_at()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\r\nbegin\r\n  if new.status = 'completed' and old.status is distinct from 'completed' then\r\n    new.completed_at := now();\r\n  end if;\r\n  return new;\r\nend;\r\n$function$\n"},{"name":"trg_installations_current_crew","enabled":"O","function":"guard_job_completion_crew()","definition":"CREATE TRIGGER trg_installations_current_crew BEFORE UPDATE OF status ON public.installations FOR EACH ROW EXECUTE FUNCTION guard_job_completion_crew('installation')","function_definition":"CREATE OR REPLACE FUNCTION public.guard_job_completion_crew()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nBEGIN\n IF auth.uid() IS NOT NULL AND public.current_user_role() IS NULL THEN RAISE EXCEPTION 'Usuario inactivo o no autorizado'; END IF;\n IF public.current_user_role()='TECNICO_RED' THEN\n   IF OLD.status::text IN ('completed','cancelled','resolved','closed') THEN\n     RAISE EXCEPTION 'La orden ya esta finalizada o cancelada';\n   END IF;\n   IF NEW.status::text IN ('completed','resolved','closed') THEN\n     PERFORM public.assert_current_job_operator(TG_ARGV[0],OLD.id);\n     IF TG_ARGV[0]='ticket' AND NEW.status::text='closed' THEN\n       RAISE EXCEPTION 'El cierre administrativo corresponde a oficina';\n     END IF;\n   END IF;\n END IF;\n RETURN NEW;\nEND $function$\n"},{"name":"trg_installations_reset_alerta","enabled":"O","function":"reset_alerta_enviada()","definition":"CREATE TRIGGER trg_installations_reset_alerta BEFORE UPDATE ON public.installations FOR EACH ROW EXECUTE FUNCTION reset_alerta_enviada()","function_definition":"CREATE OR REPLACE FUNCTION public.reset_alerta_enviada()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nbegin\n  if new.scheduled_start_at is distinct from old.scheduled_start_at then\n    new.alerta_enviada := false;\n  end if;\n  return new;\nend;\n$function$\n"},{"name":"trg_installations_reverse_on_cancel","enabled":"O","function":"reverse_inventory_on_installation_cancel()","definition":"CREATE TRIGGER trg_installations_reverse_on_cancel AFTER UPDATE ON public.installations FOR EACH ROW WHEN (((new.status = 'cancelled'::installation_status) AND (old.status IS DISTINCT FROM 'cancelled'::installation_status))) EXECUTE FUNCTION reverse_inventory_on_installation_cancel()","function_definition":"CREATE OR REPLACE FUNCTION public.reverse_inventory_on_installation_cancel()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\ndeclare\r\n  v_code text;\r\n  v_reason text;\r\nbegin\r\n  select contract_number into v_code from public.service_contracts where id = new.contract_id;\r\n  v_reason := format('Devolución automática por cancelación de instalación #%s', coalesce(v_code, new.id::text));\r\n  perform public.reverse_egreso_movements(new.id, null, v_reason);\r\n  perform public.reverse_assigned_units_by_installation(new.id, v_reason);\r\n  return new;\r\nend;\r\n$function$\n"},{"name":"trg_installations_reverse_on_delete","enabled":"O","function":"reverse_inventory_on_installation_delete()","definition":"CREATE TRIGGER trg_installations_reverse_on_delete BEFORE DELETE ON public.installations FOR EACH ROW EXECUTE FUNCTION reverse_inventory_on_installation_delete()","function_definition":"CREATE OR REPLACE FUNCTION public.reverse_inventory_on_installation_delete()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\r\ndeclare\r\n  v_code text;\r\n  v_reason text;\r\nbegin\r\n  select contract_number into v_code from public.service_contracts where id = old.contract_id;\r\n  v_reason := format('Devolución automática por eliminación de instalación #%s', coalesce(v_code, old.id::text));\r\n  perform public.reverse_egreso_movements(old.id, null, v_reason);\r\n  perform public.reverse_assigned_units_by_installation(old.id, v_reason);\r\n  return old;\r\nend;\r\n$function$\n"},{"name":"trg_installations_single_active_job","enabled":"O","function":"enforce_single_active_job()","definition":"CREATE TRIGGER trg_installations_single_active_job BEFORE UPDATE ON public.installations FOR EACH ROW EXECUTE FUNCTION enforce_single_active_job('installation')","function_definition":"CREATE OR REPLACE FUNCTION public.enforce_single_active_job()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_job_type text := tg_argv[0];\n  v_tech uuid;\n  v_conflict record;\nbegin\n  if new.status is distinct from old.status and new.status = 'in_progress' then\n    for v_tech in\n      select ja.technician_id from public.job_assignees ja\n      where ja.job_type = v_job_type and ja.job_id = new.id\n      order by ja.technician_id\n    loop\n      perform pg_advisory_xact_lock(hashtext(v_tech::text));\n\n      select * into v_conflict from public.find_other_active_job(v_tech, v_job_type, new.id);\n      if found then\n        raise exception 'Ya tienes un ticket en ejecución: % % — debes finalizarla antes de iniciar otra atención.',\n          case v_conflict.job_type when 'ticket' then 'Avería' when 'installation' then 'Alta' else 'Rutina' end,\n          coalesce(v_conflict.job_number, '#' || left(v_conflict.job_id::text, 8))\n          using errcode = 'P0001', hint = v_conflict.job_type || ':' || v_conflict.job_id;\n      end if;\n    end loop;\n  end if;\n\n  return new;\nend;\n$function$\n"},{"name":"trg_installations_updated_at","enabled":"O","function":"set_updated_at()","definition":"CREATE TRIGGER trg_installations_updated_at BEFORE UPDATE ON public.installations FOR EACH ROW EXECUTE FUNCTION set_updated_at()","function_definition":"CREATE OR REPLACE FUNCTION public.set_updated_at()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\r\nbegin\r\n  new.updated_at = now();\r\n  return new;\r\nend;\r\n$function$\n"},{"name":"trg_installations_validate_completion","enabled":"O","function":"validate_installation_completion()","definition":"CREATE TRIGGER trg_installations_validate_completion BEFORE UPDATE ON public.installations FOR EACH ROW EXECUTE FUNCTION validate_installation_completion()","function_definition":"CREATE OR REPLACE FUNCTION public.validate_installation_completion()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  svc_type public.contract_service_type := 'internet_combo';\n  contract_zone_id uuid;\n  contract_client_id uuid;\n  contract_xui_line_id integer;\n  nap_count integer;\n  ont_count integer;\n  tvbox_count integer;\nbegin\n  if new.status = 'completed' and old.status is distinct from 'completed' then\n    if new.contract_id is null then\n      raise exception 'Esta instalación no tiene un contrato vinculado; vincula uno antes de completarla (se necesita para mapear la Zona y la Caja NAP)';\n    end if;\n\n    select service_type, zone_id, client_id, xui_line_id\n      into svc_type, contract_zone_id, contract_client_id, contract_xui_line_id\n    from public.service_contracts where id = new.contract_id;\n\n    if contract_client_id is null or contract_client_id is distinct from new.client_id then\n      raise exception 'El contrato vinculado no corresponde al cliente de esta instalación; pide revisión administrativa antes de completarla' using errcode = 'P1662';\n    end if;\n\n    if new.iptv_policy_version=1 then\n      perform public.assert_installation_iptv_mode(new.id,new.client_id,new.contract_id,new.iptv_installation_mode);\n      if new.closure_operation_id is null or new.closure_payload_hash is null or new.closure_payload_hash !~ '^[a-f0-9]{64}$' then\n       raise exception 'Actualiza Campo para identificar el envío de cierre; conserva sus datos' using errcode='PIP10';\n      end if;\n    end if;\n\n    if coalesce(svc_type, 'internet_combo') = 'internet_combo' then\n      select count(*) into ont_count\n      from public.inventory_units u\n      join public.inventory_products p on p.id = u.product_id\n      join public.inventory_categories c on c.id = p.category_id\n      where u.installation_id = new.id\n        and u.status = 'assigned'\n        and u.client_id = new.client_id\n        and u.contract_id = new.contract_id\n        and c.slug = 'onu';\n      if ont_count = 0 then\n        raise exception 'Para instalaciones de internet/combo debes asignar un ONT/Módem por Serie/MAC válido (del mismo cliente y contrato) antes de completarla' using errcode = 'P1660';\n      end if;\n\n      if contract_xui_line_id is not null and (new.iptv_policy_version is distinct from 1 or new.iptv_installation_mode='rayco_tv_box') then\n        select count(*) into tvbox_count\n        from public.inventory_units u\n        join public.inventory_products p on p.id = u.product_id\n        join public.inventory_categories c on c.id = p.category_id\n        where u.installation_id = new.id\n          and u.status = 'assigned'\n          and u.client_id = new.client_id\n          and u.contract_id = new.contract_id\n          and c.slug = 'tvbox';\n        if tvbox_count = 0 then\n          raise exception 'Este servicio incluye IPTV -- debes asignar un TV Box por Serie/MAC válido (del mismo cliente y contrato) antes de completarla' using errcode = 'P1661';\n        end if;\n      end if;\n    end if;\n\n    if contract_zone_id is null then\n      raise exception 'Debes asignar la Zona del servicio antes de completar la instalación';\n    end if;\n\n    select count(*) into nap_count\n    from public.fo_nap_puertos\n    where contract_id = new.contract_id and estado = 'ocupado';\n    if nap_count = 0 then\n      raise exception 'Debes asignar la Caja NAP del servicio antes de completar la instalación';\n    end if;\n  end if;\n\n  return new;\nend;\n$function$\n"},{"name":"trg_track_work_session","enabled":"O","function":"track_job_work_session()","definition":"CREATE TRIGGER trg_track_work_session AFTER UPDATE ON public.installations FOR EACH ROW EXECUTE FUNCTION track_job_work_session('installation')","function_definition":"CREATE OR REPLACE FUNCTION public.track_job_work_session()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_job_type text := tg_argv[0];\nbegin\n  if new.status is distinct from old.status then\n    if new.status = 'in_progress' and old.status <> 'in_progress' then\n      if not exists (\n        select 1 from public.job_work_sessions\n        where job_type = v_job_type and job_id = new.id and ended_at is null\n      ) then\n        insert into public.job_work_sessions (job_type, job_id, started_at)\n        values (v_job_type, new.id, now());\n      end if;\n    elsif old.status = 'in_progress' and new.status <> 'in_progress' then\n      update public.job_work_sessions\n      set ended_at = now(),\n          end_reason = case\n            when new.status::text in ('completed', 'resolved', 'closed') then 'finished'\n            when new.status::text = 'cancelled' then 'cancelled_order'\n            else 'paused'\n          end\n      where job_type = v_job_type and job_id = new.id and ended_at is null;\n    end if;\n  end if;\n  return new;\nend;\n$function$\n"}],"force_rls":false,"constraints":[{"name":"installations_assigned_to_fkey","definition":"FOREIGN KEY (assigned_to) REFERENCES profiles(id)"},{"name":"installations_client_id_fkey","definition":"FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE CASCADE"},{"name":"installations_closure_receipt_check","definition":"CHECK ((((closure_operation_id IS NULL) AND (closure_payload_hash IS NULL)) OR ((closure_operation_id IS NOT NULL) AND (closure_payload_hash IS NOT NULL) AND (closure_payload_hash ~ '^[a-f0-9]{64}$'::text))))"},{"name":"installations_contract_id_fkey","definition":"FOREIGN KEY (contract_id) REFERENCES service_contracts(id) ON DELETE CASCADE"},{"name":"installations_created_by_fkey","definition":"FOREIGN KEY (created_by) REFERENCES profiles(id)"},{"name":"installations_iptv_mode_check","definition":"CHECK (((iptv_installation_mode IS NULL) OR (iptv_installation_mode = ANY (ARRAY['smart_tv_app'::text, 'customer_device'::text, 'rayco_tv_box'::text]))))"},{"name":"installations_iptv_policy_check","definition":"CHECK (((iptv_policy_version IS NULL) OR (iptv_policy_version = 1)))"},{"name":"installations_pkey","definition":"PRIMARY KEY (id)"},{"name":"installations_points_check","definition":"CHECK (((points >= (0)::numeric) AND (points < 'Infinity'::numeric)))"}]},{"acl":["postgres=arwdDxtm/postgres","anon=arwdDxtm/postgres","authenticated=arwdDxtm/postgres","service_role=arwdDxtm/postgres"],"rls":true,"name":"service_contracts","owner":"postgres","columns":[{"name":"id","type":"uuid","default":"gen_random_uuid()","nullable":false},{"name":"contract_number","type":"text","default":null,"nullable":true},{"name":"client_id","type":"uuid","default":null,"nullable":false},{"name":"plan_id","type":"uuid","default":null,"nullable":true},{"name":"monthly_fee","type":"numeric(10,2)","default":"0","nullable":false},{"name":"status","type":"contract_status","default":"'active'::contract_status","nullable":false},{"name":"start_date","type":"date","default":"CURRENT_DATE","nullable":false},{"name":"end_date","type":"date","default":null,"nullable":true},{"name":"billing_day","type":"integer","default":"1","nullable":true},{"name":"payment_method","type":"text","default":"'cash'::text","nullable":true},{"name":"created_at","type":"timestamp with time zone","default":"now()","nullable":false},{"name":"updated_at","type":"timestamp with time zone","default":"now()","nullable":false},{"name":"mikrotik_device_id","type":"uuid","default":null,"nullable":true},{"name":"pppoe_username","type":"text","default":null,"nullable":true},{"name":"mikrotik_profile","type":"text","default":null,"nullable":true},{"name":"xui_line_id","type":"integer","default":null,"nullable":true},{"name":"xui_username","type":"text","default":null,"nullable":true},{"name":"debt_hold_status","type":"debt_hold_status","default":"'none'::debt_hold_status","nullable":false},{"name":"debt_hold_flagged_at","type":"timestamp with time zone","default":null,"nullable":true},{"name":"debt_hold_applied_at","type":"timestamp with time zone","default":null,"nullable":true},{"name":"debt_hold_invoice_id","type":"uuid","default":null,"nullable":true},{"name":"mikrotik_profile_before_hold","type":"text","default":null,"nullable":true},{"name":"installation_address","type":"text","default":null,"nullable":true},{"name":"installation_reference","type":"text","default":null,"nullable":true},{"name":"latitude","type":"double precision","default":null,"nullable":true},{"name":"longitude","type":"double precision","default":null,"nullable":true},{"name":"zone_id","type":"uuid","default":null,"nullable":true},{"name":"client_code","type":"text","default":null,"nullable":true},{"name":"priority","type":"text","default":"'medium'::text","nullable":false},{"name":"service_type","type":"contract_service_type","default":"'internet_combo'::contract_service_type","nullable":false},{"name":"is_courtesy","type":"boolean","default":"false","nullable":false},{"name":"courtesy_reason","type":"text","default":null,"nullable":true}],"indexes":[{"name":"idx_service_contracts_client_code_unique","definition":"CREATE UNIQUE INDEX idx_service_contracts_client_code_unique ON public.service_contracts USING btree (client_code) WHERE (client_code IS NOT NULL)"},{"name":"idx_service_contracts_client_id","definition":"CREATE INDEX idx_service_contracts_client_id ON public.service_contracts USING btree (client_id)"},{"name":"idx_service_contracts_plan_id","definition":"CREATE INDEX idx_service_contracts_plan_id ON public.service_contracts USING btree (plan_id)"},{"name":"idx_service_contracts_pppoe_unique","definition":"CREATE UNIQUE INDEX idx_service_contracts_pppoe_unique ON public.service_contracts USING btree (mikrotik_device_id, pppoe_username) WHERE ((mikrotik_device_id IS NOT NULL) AND (pppoe_username IS NOT NULL))"},{"name":"idx_service_contracts_status","definition":"CREATE INDEX idx_service_contracts_status ON public.service_contracts USING btree (status)"},{"name":"idx_service_contracts_zone","definition":"CREATE INDEX idx_service_contracts_zone ON public.service_contracts USING btree (zone_id) WHERE (zone_id IS NOT NULL)"},{"name":"service_contracts_contract_number_key","definition":"CREATE UNIQUE INDEX service_contracts_contract_number_key ON public.service_contracts USING btree (contract_number)"},{"name":"service_contracts_pkey","definition":"CREATE UNIQUE INDEX service_contracts_pkey ON public.service_contracts USING btree (id)"}],"policies":[{"cmd":"ALL","name":"service_contracts_staff_only","check":"(current_user_role() = ANY (ARRAY['SUPERADMIN'::user_role, 'ADMIN'::user_role, 'TECNICO_RED'::user_role, 'SOPORTE'::user_role, 'FACTURACION'::user_role]))","roles":["authenticated"],"using":"(current_user_role() = ANY (ARRAY['SUPERADMIN'::user_role, 'ADMIN'::user_role, 'TECNICO_RED'::user_role, 'SOPORTE'::user_role, 'FACTURACION'::user_role]))","permissive":"PERMISSIVE"}],"triggers":[{"name":"contract_administrative_guard","enabled":"O","function":"contract_administrative_guard()","definition":"CREATE TRIGGER contract_administrative_guard BEFORE INSERT OR UPDATE OF status, client_id ON public.service_contracts FOR EACH ROW EXECUTE FUNCTION contract_administrative_guard()","function_definition":"CREATE OR REPLACE FUNCTION public.contract_administrative_guard()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\ndeclare previous_parent uuid; owner_name text; parent_status public.client_status;\nbegin\n if tg_op='UPDATE' then previous_parent:=old.client_id; end if;\n perform 1 from public.clients where id in (new.client_id,previous_parent) order by id for update;\n select status into parent_status from public.clients where id=new.client_id;\n if parent_status is null then raise exception 'No se puede validar la ficha' using errcode='42501'; end if;\n if new.status<>'cancelled' and parent_status='retired' then raise exception 'Ficha retirada: requiere revisión autorizada' using errcode='PBA02'; end if;\n if new.status='cancelled' and (tg_op='INSERT' or old.status is distinct from new.status) then\n  select pg_get_userbyid(proowner) into owner_name from pg_proc where oid='public.contract_cancel_administrative(uuid,timestamptz,boolean)'::regprocedure;\n  if current_user<>owner_name or current_setting('app.client_retirement_id',true) is distinct from new.client_id::text then\n   raise exception 'Utilice la baja administrativa confirmada' using errcode='42501';\n  end if;\n end if;\n return new;\nend $function$\n"},{"name":"trg_service_contracts_free_nap_puerto","enabled":"O","function":"free_nap_puerto_on_contract_delete()","definition":"CREATE TRIGGER trg_service_contracts_free_nap_puerto BEFORE DELETE ON public.service_contracts FOR EACH ROW EXECUTE FUNCTION free_nap_puerto_on_contract_delete()","function_definition":"CREATE OR REPLACE FUNCTION public.free_nap_puerto_on_contract_delete()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nbegin\n  update public.fo_nap_puertos\n  set\n    estado = 'libre',\n    client_id = null,\n    contract_id = null,\n    notes = trim(both ' | ' from coalesce(notes || ' | ', '')\n      || 'Fase 156: liberado automaticamente al eliminar el contrato '\n      || old.id::text || ' (' || to_char(now(), 'YYYY-MM-DD HH24:MI') || ')')\n  where contract_id = old.id\n    and estado = 'ocupado';\n  return old;\nend;\n$function$\n"},{"name":"trg_service_contracts_number","enabled":"O","function":"set_contract_number()","definition":"CREATE TRIGGER trg_service_contracts_number BEFORE INSERT ON public.service_contracts FOR EACH ROW EXECUTE FUNCTION set_contract_number()","function_definition":"CREATE OR REPLACE FUNCTION public.set_contract_number()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\r\nbegin\r\n  if new.contract_number is null then\r\n    new.contract_number := public.generate_contract_number();\r\n  end if;\r\n  return new;\r\nend;\r\n$function$\n"},{"name":"trg_service_contracts_updated_at","enabled":"O","function":"set_updated_at()","definition":"CREATE TRIGGER trg_service_contracts_updated_at BEFORE UPDATE ON public.service_contracts FOR EACH ROW EXECUTE FUNCTION set_updated_at()","function_definition":"CREATE OR REPLACE FUNCTION public.set_updated_at()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\r\nbegin\r\n  new.updated_at = now();\r\n  return new;\r\nend;\r\n$function$\n"}],"force_rls":false,"constraints":[{"name":"service_contracts_billing_day_check","definition":"CHECK (((billing_day >= 1) AND (billing_day <= 31)))"},{"name":"service_contracts_client_id_fkey","definition":"FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE CASCADE"},{"name":"service_contracts_contract_number_key","definition":"UNIQUE (contract_number)"},{"name":"service_contracts_debt_hold_invoice_id_fkey","definition":"FOREIGN KEY (debt_hold_invoice_id) REFERENCES invoices(id) ON DELETE SET NULL"},{"name":"service_contracts_mikrotik_device_id_fkey","definition":"FOREIGN KEY (mikrotik_device_id) REFERENCES mikrotik_devices(id)"},{"name":"service_contracts_pkey","definition":"PRIMARY KEY (id)"},{"name":"service_contracts_plan_id_fkey","definition":"FOREIGN KEY (plan_id) REFERENCES plans(id)"},{"name":"service_contracts_priority_check","definition":"CHECK ((priority = ANY (ARRAY['high'::text, 'medium'::text, 'low'::text])))"},{"name":"service_contracts_zone_id_fkey","definition":"FOREIGN KEY (zone_id) REFERENCES zones(id)"}]}],"read_only":"on","existing_proposal_functions":[]}$schema_baseline$::jsonb; v_actual jsonb;
begin
  select jsonb_build_object(
 'read_only',current_setting('transaction_read_only'),'at',now(),
 'tables',(select jsonb_agg(jsonb_build_object(
   'name',c.relname,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,
   'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'nullable',not a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
   'constraints',(select jsonb_agg(jsonb_build_object('name',p.conname,'definition',pg_get_constraintdef(p.oid)) order by p.conname) from pg_constraint p where p.conrelid=c.oid),
   'indexes',(select jsonb_agg(jsonb_build_object('name',i.indexname,'definition',i.indexdef) order by i.indexname) from pg_indexes i where i.schemaname='public' and i.tablename=c.relname),
   'policies',(select jsonb_agg(jsonb_build_object('name',p.policyname,'permissive',p.permissive,'roles',p.roles,'cmd',p.cmd,'using',p.qual,'check',p.with_check) order by p.policyname) from pg_policies p where p.schemaname='public' and p.tablename=c.relname),
   'triggers',(select jsonb_agg(jsonb_build_object('name',t.tgname,'definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled,'function',t.tgfoid::regprocedure::text,'function_definition',pg_get_functiondef(t.tgfoid)) order by t.tgname) from pg_trigger t where t.tgrelid=c.oid and not t.tgisinternal)
 ) order by c.relname) from pg_class c where c.relnamespace='public'::regnamespace and c.relname in ('clients','service_contracts','installations')),
 'existing_proposal_functions',(select coalesce(jsonb_agg(p.oid::regprocedure::text),'[]'::jsonb) from pg_proc p where p.pronamespace='public'::regnamespace and p.proname in ('discard_unfulfilled_client_prospect','guard_unfulfilled_prospect_discard','guard_discarded_prospect_child'))
) into v_actual;
  if (v_actual - 'at' - 'read_only') is distinct from (v_expected - 'at' - 'read_only') then
    raise exception 'SCHEMA_DRIFT: detener sin aplicar; conservar respaldo y revisar diferencias';
  end if;
  if md5(pg_get_functiondef('public.current_user_role()'::regprocedure)) <> '67d13ed6e8c78b73b623b8a76d325761' then raise exception 'ROLE_HELPER_DRIFT'; end if;
  if not exists(select 1 from pg_attribute where attrelid='public.profiles'::regclass and attname='active' and atttypid='boolean'::regtype and not attisdropped)
    or not exists(select 1 from pg_attribute where attrelid='public.profiles'::regclass and attname='role' and atttypid='public.user_role'::regtype and not attisdropped) then raise exception 'PROFILE_CONTRACT_DRIFT'; end if;
end $preflight$;
rollback;
